"""Loads config/client.yaml (generated by `python -m app.setup render`) into a ClientConfig.

A missing file is not an error: it means the engine defaults (domain/client_config.py), so an engine
checkout and every test keep working without a client profile.
"""
from __future__ import annotations

from pathlib import Path

import yaml

from domain.client_config import DEFAULT_CLIENT_CONFIG, ClientConfig, client_config_from_dict

DEFAULT_CLIENT_CONFIG_PATH = Path(__file__).resolve().parents[2] / "config" / "client.yaml"


def load_client_config(path: Path = DEFAULT_CLIENT_CONFIG_PATH) -> ClientConfig:
    if not path.is_file():
        return DEFAULT_CLIENT_CONFIG
    with open(path, "r", encoding="utf-8") as f:
        return client_config_from_dict(yaml.safe_load(f))
